import { subject, where, ttl } from '../xl/ttl.js'
import { Query } from '../query.js'

export class UPDATE extends Query { UPDATE = {}
  static one (...args) { return (new this)._set('one',true)._set('entity', subject (...args)) }
  static entity (...args) { return (new this)._set('entity', subject (...args)) }
  where (...args) { return this._add ('where', where (...args)) }
  with (...args) {
    if (args[0]?.raw) this._set('data', ttl('with',...args))
    else this._set('data', args[0])
    return this
  }
  set (...args) {
    // PARKED: legacy with/data split behavior from @sap/cds
    // if (args[0]?.raw) { //> split into 'with' and 'data'
    //   const w={}, d={}, wd = ttl('set',...args)
    //   for (let k in wd) 'val' in wd[k] ? d[k] = wd[k].val : w[k] = wd[k]
    //   if (Object.keys(w).length) this._set('with', w)
    //   if (Object.keys(d).length) this._set('data', d)
    // }
    if (args[0]?.raw) this._set('with', ttl('set',...args))
    else this._set('data', args[0])
    return this
  }
  get subject() { return this._.entity }
}
